rules.logic:
// Match the native feed section card's outer style
element.style.background = 'var(--card, #fff)';
element.style.borderRadius = '';
element.style.gap = '';
element.style.padding = '0';

// Match the native "Trending" / "Home & Garden" heading style exactly
element.style.padding = '0';
element.style.margin = '0';
element.style.paddingBottom = '1rem';   // pb-4
element.style.borderTop = 'none';
element.style.marginTop = '0';
element.style.display = 'flex';

const h2 = element.querySelector('h2');
if (h2) {
  h2.style.fontSize = '1.25rem';      // text-xl
  h2.style.lineHeight = '1.75rem';    // leading-normal
  h2.style.letterSpacing = '-0.025em'; // tracking-tight
  h2.style.fontWeight = '700';        // font-bold
  h2.style.color = 'rgb(17,24,39)';   // text-gray-900
  h2.style.display = 'flex';
  h2.style.margin = '0';
  h2.style.padding = '0';
}

// Make each Taboola card row display as a matching CSS grid (like the native @md/grid layout)
element.style.display = 'grid';
element.style.gridTemplateColumns = 'repeat(auto-fill, minmax(180px, 1fr))';
element.style.gap = '1.5rem 1.5rem'; // gap-x-6 gap-y-4
element.style.marginBottom = '1rem';

// Match native card item layout: flex-col, gap-4, rounded corners
element.style.display = 'flex';
element.style.flexDirection = 'column';
element.style.gap = '1rem';
element.style.textDecoration = 'none';
element.style.borderRadius = '0.5rem';
element.style.cursor = 'pointer';
element.style.overflow = 'hidden';
element.style.background = 'transparent';
element.style.width = '100%';
element.style.boxSizing = 'border-box';

// Match native image wrapper: rounded-2xl, overflow-hidden, aspect-square
element.style.position = 'relative';
element.style.overflow = 'hidden';
element.style.borderRadius = '1rem'; // rounded-2xl
element.style.aspectRatio = '1 / 1';
element.style.width = '100%';
element.style.transition = 'box-shadow 150ms';

// Match native img style: object-cover, scale, transition
element.style.position = 'absolute';
element.style.inset = '0';
element.style.width = '100%';
element.style.height = '100%';
element.style.backgroundSize = 'cover';
element.style.backgroundPosition = 'center';
element.style.borderRadius = '0.5rem'; // rounded-lg
element.style.transform = 'scale(1.01)';
element.style.transition = 'transform 200ms ease';

// Match native text column layout
element.style.display = 'flex';
element.style.flexDirection = 'column';
element.style.gap = '0.125rem';
element.style.width = '100%';

// Match native h2 card title: font-bold, text-base, line-clamp-4, pb-0.5
element.style.fontWeight = '700';
element.style.fontSize = '1rem';      // text-base
element.style.lineHeight = '1.625';
element.style.color = 'rgb(17,24,39)'; // text-gray-900
element.style.display = '-webkit-box';
element.style.webkitLineClamp = '3';
element.style.webkitBoxOrient = 'vertical';
element.style.overflow = 'hidden';
element.style.paddingBottom = '0.125rem'; // pb-0.5
element.style.marginBottom = '0';
element.style.textDecoration = 'none';
element.style.WebkitLineClamp = '3';

// Match native "source/duration" sub-label style
element.style.fontSize = '0.75rem';   // text-xs
element.style.color = 'rgb(107,114,128)'; // text-gray-500
element.style.fontWeight = '400';
element.style.lineHeight = '1.5';
element.style.display = 'block';
element.style.textDecoration = 'none';

// Add hover class styling to match native "group-hover:shadow-lg"
if (!element.dataset.hoverBound) {
  element.dataset.hoverBound = 'true';
  element.addEventListener('mouseenter', () => {
    const thumb = element.querySelector('.thumbBlock_holder');
    if (thumb) thumb.style.boxShadow = '0 10px 15px -3px rgba(0,0,0,.1),0 4px 6px -4px rgba(0,0,0,.1)';
    const img = element.querySelector('.thumbBlock');
    if (img) img.style.transform = 'scale(1.05)';
  });
  element.addEventListener('mouseleave', () => {
    const thumb = element.querySelector('.thumbBlock_holder');
    if (thumb) thumb.style.boxShadow = '';
    const img = element.querySelector('.thumbBlock');
    if (img) img.style.transform = 'scale(1.01)';
  });
}

// Match the native section wrapper: flex flex-col @container/card text-card-foreground bg-card border-gray-500
element.style.display = 'flex';
element.style.flexDirection = 'column';
element.style.background = '#fff';
element.style.color = 'inherit';

// Mirror the exact classes on the native section: flex flex-col @container/card bg-card text-card-foreground border-gray-500
element.style.display = 'flex';
element.style.flexDirection = 'column';
element.style.background = '#fff';
element.style.border = 'none';
element.style.boxShadow = 'none';
element.style.borderRadius = '0';
element.style.padding = '0';
element.style.gap = '0';
